import fs from 'node:fs/promises';import path from 'node:path';import {createHmac} from 'node:crypto';
export const root=path.join(process.env.LOCALAPPDATA,'FVI-QA-Private-20260925'),own=path.join(root,'reference-dev-positive-20261004'),tenant='aa5ed999-69eb-41a0-a9c6-fbb439efcffe',host='https://dev.app.reconiq.example';await fs.mkdir(own,{recursive:true});
const transport=JSON.parse(await fs.readFile(path.join(root,'FVI-QA-TRANSPORT-DEV-20261002.json'),'utf8'));if(transport.projectRef!=='YOUR_PROJECT_REF'||transport.anonKey.startsWith('sb_secret_'))throw Error('Exact DEV public transport required');export {transport};
function totp(secret){let bits='';for(const c of secret.toUpperCase().replaceAll('=','')){const n='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'.indexOf(c);if(n<0)throw Error('Invalid protected TOTP seed');bits+=n.toString(2).padStart(5,'0');}const bs=[];for(let i=0;i+8<=bits.length;i+=8)bs.push(parseInt(bits.slice(i,i+8),2));const b=Buffer.alloc(8);b.writeBigUInt64BE(BigInt(Math.floor(Date.now()/30000)));const d=createHmac('sha1',Buffer.from(bs)).update(b).digest();return String((d.readUInt32BE(d[d.length-1]&15)&0x7fffffff)%1000000).padStart(6,'0');}
async function auth(endpoint,body,token){const r=await fetch(transport.apiUrl+'/auth/v1/'+endpoint,{method:'POST',headers:{apikey:transport.anonKey,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(25000)}),j=await r.json();if(!r.ok)throw Error('Ordinary owned DEV Auth '+r.status+' '+(j.code??j.error_code??''));return j;}
export async function actor(kind){let id,email,password,mfa;if(kind==='viewer'){const s=JSON.parse(await fs.readFile(path.join(root,'reference-dev-viewer-20261004/provision.json'),'utf8'));id=s.user_id;email=s.email;password=s.password;mfa=s;}else{const c=await fs.readFile(path.join(root,'FVI-QA-Access-DEV-'+kind+'-20260925.cred'),'utf8'),field=n=>c.split(/\r?\n/).find(l=>l.startsWith('- '+n+': ')||l.startsWith(n+': '))?.split(': ').slice(1).join(': ').trim().replace(/^`|`$/g,'');id=field('User ID');email=field('Account');password=field('Temporary password');mfa=JSON.parse(await fs.readFile(path.join(root,'governance-approval-hosted-20261002/DEV-'+kind+'-OWNED-MFA.json'),'utf8'));}
if(mfa.user_id!==id||mfa.tenant_id&&mfa.tenant_id!==tenant||mfa.tenant&&mfa.tenant!==tenant)throw Error('Protected actor/MFA mapping differs');const file=path.join(own,kind+'-session.json');let session;try{session=JSON.parse(await fs.readFile(file,'utf8'));const c=JSON.parse(Buffer.from(session.access_token.split('.')[1],'base64url'));if(c.sub!==id||c.aal!=='aal2'||c.exp*1000<Date.now()+300000)session=null;}catch{}if(!session){const signed=await auth('token?grant_type=password',{email,password}),ch=await auth('factors/'+mfa.factor_id+'/challenge',{},signed.access_token);session=await auth('factors/'+mfa.factor_id+'/verify',{challenge_id:ch.id,code:totp(mfa.totp_secret)},signed.access_token);await fs.writeFile(file,JSON.stringify(session));}const claims=JSON.parse(Buffer.from(session.access_token.split('.')[1],'base64url'));if(claims.sub!==id||claims.aal!=='aal2')throw Error('Actual provider AAL2 required');const headers={apikey:transport.anonKey,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},user=await fetch(transport.apiUrl+'/auth/v1/user',{headers});if(!user.ok||(await user.json()).id!==id)throw Error('Current provider identity validation failed');const a={kind,id,session,headers};const role=await api(a,'tenant_members',{select:'role,active',tenant_id:'eq.'+tenant,user_id:'eq.'+id});if(role.http!==200||role.data.length!==1||!role.data[0].active||role.data[0].role!==(kind==='viewer'?'tenant_viewer':'tenant_admin'))throw Error('Current exact owned DEV role unavailable');return a;}
export async function api(a,name,query,body,method=body?'POST':'GET'){const r=await fetch(transport.apiUrl+'/rest/v1/'+name+(query?'?'+new URLSearchParams(query):''),{method,headers:{...a.headers,...(method!=='GET'?{Prefer:'return=representation'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(25000)});const text=await r.text();return {http:r.status,data:text?JSON.parse(text):null};}
export async function rpc(a,name,args){return api(a,'rpc/'+name,null,args);}
export async function audit(a,action,type,id,context){const result=await api(a,'audit_log',null,{tenant_id:tenant,actor_user_id:a.id,scope:'tenant',action,resource_type:type,resource_id:id,context});if(result.http<200||result.http>=300)throw Error('Truthful QA audit refused '+result.http+' '+result.data?.code);return result.data;}
